<template><DeliveryShell title="配送订单详情" :controller="controller"><template v-if="order"><view class="delivery-card"><view class="delivery-row"><text class="delivery-label">{{ order._status._title }}</text><text class="delivery-amount">¥{{ order.pay_price }}</text></view><text>{{ order._status._msg }}</text></view><view v-if="order.store" class="delivery-card"><text class="delivery-label">{{ order.store.name }}</text><text>{{ order.store.address }} {{ order.store.detailed_address }}</text><view class="delivery-controls"><button :disabled="!order.store.phone" @tap="phone(order.store.phone)">联系门店</button><button :disabled="order.store.latitude===null||order.store.longitude===null" @tap="mapStore">门店位置</button></view></view><view class="delivery-card"><text class="delivery-label">收件信息</text><text>{{ order.real_name||order.nickname }} · {{ order.user_phone }}</text><view>{{ order.user_address }}</view><view class="delivery-controls"><button :disabled="!order.user_phone" @tap="phone(order.user_phone)">联系收件人</button><button :disabled="order.latitude===null||order.longitude===null" @tap="mapCustomer">收件地址位置</button></view><text v-if="order.latitude===null||order.longitude===null" class="delivery-muted">该地址未提供有效坐标，可通过电话确认。</text></view><view class="delivery-card"><text class="delivery-label">订单商品</text><DeliveryCart v-for="cart in order.cartInfo" :key="cart.id" :cart="cart" counts /></view><view v-if="order.give_coupon.length||order.give_integral" class="delivery-card"><text class="delivery-label">下单赠送</text><text v-if="order.give_integral">赠送积分 {{ order.give_integral }}</text><view v-for="coupon in order.give_coupon" :key="coupon.id">{{ coupon.coupon_title }}</view></view><view class="delivery-card"><view class="delivery-row"><text>订单号</text><text class="delivery-link" @tap="copy">{{ order.order_id }} · 复制</text></view><view class="delivery-row"><text>创建时间</text><text>{{ order._add_time }}</text></view><view class="delivery-row"><text>支付时间</text><text>{{ order._pay_time }}</text></view><view class="delivery-row"><text>支付方式</text><text>{{ order._status._payType||order.pay_type }}</text></view><view class="delivery-row"><text>配送方式</text><text>{{ order._status._deliveryType }}</text></view><view v-if="order.mark">客户留言：{{ order.mark }}</view><view v-for="(row,index) in formRows" :key="index" class="delivery-row"><text>{{ row.name }}</text><text>{{ row.value }}</text></view></view><view class="delivery-card"><text class="delivery-label">费用明细</text><view class="delivery-row"><text>商品金额</text><text>¥{{ gross }}</text></view><view class="delivery-row"><text>运费</text><text>¥{{ order.pay_postage }}</text></view><view class="delivery-row"><text>会员优惠</text><text>-¥{{ order.vip_true_price }}</text></view><view class="delivery-row"><text>优惠券抵扣</text><text>-¥{{ order.coupon_price }}</text></view><view class="delivery-row"><text>积分抵扣</text><text>-¥{{ order.deduction_price }} · {{ order.pay_integral }} 积分</text></view><view class="delivery-row"><text>活动优惠</text><text>-¥{{ order.promotions_price }}</text></view><view class="delivery-row"><text>首单优惠</text><text>-¥{{ order.first_order_price }}</text></view><view v-for="(promotion,index) in order.promotions_detail" :key="index" class="delivery-row"><text>{{ promotion.title||'促销活动' }}</text><text>-¥{{ promotion.promotions_price }}</text></view><view class="delivery-divider" /><view class="delivery-row"><text>实付款</text><text class="delivery-amount">¥{{ order.pay_price }}</text></view></view><view class="delivery-card"><text v-if="!order.actions.writeoff.available" class="delivery-reason">{{ order.actions.writeoff.reason||'当前订单不能确认送达' }}</text><view class="delivery-controls"><button :disabled="!order.actions.writeoff.available||controller.busy.value" @tap="controller.go('scanDetail',{orderId:order.id})">核对商品并确认送达</button><button @tap="controller.go('scanDetail',{orderId:order.id,tab:'records'})">查看核销记录</button></view></view></template></DeliveryShell></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import DeliveryShell from '@/components/deliveryWorkbench/DeliveryShell.vue';import DeliveryCart from '@/components/deliveryWorkbench/DeliveryCart.vue';import {useDeliveryWorkbench} from '@/composables/useDeliveryWorkbench';import {isDeliveryDetail,deliveryInt} from '@/utils/deliveryWorkbench';import {merchantFormRows,merchantMoneySum} from '@/utils/merchantOrders';import type {DeliveryOrderDetail} from '@/types/deliveryWorkbench';
const order=ref<DeliveryOrderDetail|null>(null);let orderId=0;
const controller=useDeliveryWorkbench({query(query){orderId=Number(query.orderId||query.id);},clear(){order.value=null;},async load(c){if(!deliveryInt(orderId,1))throw Error('订单编号无效');const valid=c.fence(),row=await c.read(`orders/${orderId}`,isDeliveryDetail);if(!valid())return;if(row.data.id!==orderId)throw Error('订单响应不匹配');order.value=row.data;}});
const formRows=computed(()=>merchantFormRows(order.value?.custom_form)),gross=computed(()=>order.value?merchantMoneySum([order.value.total_price,order.value.vip_true_price]):'0.00');
function phone(value:string){if(controller.current()&&order.value&&[order.value.user_phone,order.value.store?.phone].includes(value)&&value)uni.makePhoneCall({phoneNumber:value});}
function mapStore(){const store=order.value?.store;if(controller.current()&&store&&store.latitude!==null&&store.longitude!==null)uni.openLocation({latitude:store.latitude,longitude:store.longitude,name:store.name,address:`${store.address} ${store.detailed_address}`});}
function mapCustomer(){const value=order.value;if(controller.current()&&value&&value.latitude!==null&&value.longitude!==null)uni.openLocation({latitude:value.latitude,longitude:value.longitude,name:value.real_name||value.nickname,address:value.user_address});}
function copy(){if(controller.current()&&order.value)uni.setClipboardData({data:order.value.order_id});}
</script>
